// On-demand loading of stroke data ({ strokes, medians }) generated by scripts/build-data.ts.
// Each character lives in its own small file, so the JS bundle doesn't grow with the decks.
import type { CharacterJson } from 'hanzi-writer';
import { charFile } from '@/domain/charFile.ts';

const pending = new Map<string, Promise<CharacterJson>>();
const loaded = new Map<string, CharacterJson>();

export const charUrl = (c: string) =>
  `${import.meta.env.BASE_URL.replace(/\/?$/, '/')}hanzi/${charFile(c)}`;

// Resolved data or undefined; lets cached characters render without a loading frame.
export const getCachedCharData = (c: string) => loaded.get(c);

// Fetches stroke data once per character; concurrent calls share one request.
// A failed request is not cached, so the next call retries.
export function loadCharData(c: string): Promise<CharacterJson> {
  const cached = loaded.get(c);
  if (cached) return Promise.resolve(cached);
  let p = pending.get(c);
  if (!p) {
    p = fetch(charUrl(c))
      .then((res) => {
        if (!res.ok)
          throw new Error(`Stroke data for ${c}: HTTP ${res.status}`);
        // SPA fallbacks answer missing files with 200 + index.html.
        if (!res.headers.get('content-type')?.includes('json'))
          throw new Error(`Stroke data for ${c}: not found (${charUrl(c)})`);
        return res.json() as Promise<CharacterJson>;
      })
      .then((data) => {
        loaded.set(c, data);
        return data;
      })
      .finally(() => pending.delete(c));
    pending.set(c, p);
  }
  return p;
}

// Fire-and-forget warm-up, e.g. for neighbors of the current character.
export function prefetchCharData(chars: Iterable<string>) {
  for (const c of chars) loadCharData(c).catch(() => {});
}

// Test helper.
export function _resetCharDataCache() {
  pending.clear();
  loaded.clear();
}
